params.spec:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Every audited event for the current selection by hour of day and day of week, over the last 7 days in UTC - one cell is one specific hour, not an average, because a seven-day window holds each hour of the week exactly once. Strength is volume on a log scale, so a quiet hour stays visible beside a busy one; a bare grey slot is an hour with no events at all. The current hour is still filling, so it is outlined rather than coloured: coloured, its first minutes read as a sudden drop after the full hours before it. Fixed window: this panel does not follow the time picker. No noise gate: it measures presence, so it will not reconcile with Signal events. UTC is stated rather than localised so the chart reads the same for every viewer, whatever their timezone - read the rhythm, not the clock.",
  "title": {
    "text": {
      "expr": "extent(pluck(data('hours'), 'doc_count'))[1] > 0 ? '' : 'No activity for this selection in the last 7 days'"
    }
  },
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "config": {
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 11
    },
    "view": {
      "stroke": null
    },
    "title": {
      "fontSize": 12,
      "fontWeight": 500,
      "anchor": "start"
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 11
    }
  },
  "data": {
    "name": "hours",
    "url": {
      "index": "logs-elastic_cloud.serverless_audit.otel-*",
      "body": {
        "size": 0,
        "query": {
          "bool": {
            "must": [
              "%dashboard_context-must_clause%",
              {
                "range": {
                  "@timestamp": {
                    "gte": "now-167h/h",
                    "lte": "now"
                  }
                }
              }
            ],
            "must_not": [
              "%dashboard_context-must_not_clause%"
            ],
            "filter": [
              "%dashboard_context-filter_clause%"
            ]
          }
        },
        "aggs": {
          "hours": {
            "date_histogram": {
              "field": "@timestamp",
              "fixed_interval": "1h",
              "time_zone": "UTC",
              "min_doc_count": 0,
              "extended_bounds": {
                "min": "now-167h/h",
                "max": "now"
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.hours.buckets"
    }
  },
  "transform": [
    {
      "calculate": "utchours(datum.key)",
      "as": "hour"
    },
    {
      "calculate": "['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][(utcday(datum.key) + 6) % 7]",
      "as": "day"
    },
    {
      "calculate": "utcFormat(datum.key, '%a %d %b, %H:00') + '–' + utcFormat(datum.key + 3600000, '%H:00') + ' UTC'",
      "as": "when"
    },
    {
      "calculate": "datum.key + 3600000 > now()",
      "as": "partial"
    },
    {
      "calculate": "datum.partial ? 'in progress - ' + format(datum.doc_count, ',') + ' so far' : format(datum.doc_count, ',')",
      "as": "eventsText"
    }
  ],
  "encoding": {
    "x": {
      "field": "hour",
      "type": "ordinal",
      "scale": {
        "paddingInner": 0.1
      },
      "axis": {
        "title": "Hour of day (UTC)",
        "orient": "top",
        "labelAngle": 0,
        "ticks": false,
        "domain": false,
        "titleOpacity": {
          "expr": "extent(pluck(data('hours'), 'doc_count'))[1] > 0 ? 1 : 0"
        },
        "labelOpacity": {
          "expr": "extent(pluck(data('hours'), 'doc_count'))[1] > 0 ? 1 : 0"
        },
        "labelExpr": "datum.value % 3 === 0 ? datum.label : ''"
      }
    },
    "y": {
      "field": "day",
      "type": "ordinal",
      "sort": [
        "Mon",
        "Tue",
        "Wed",
        "Thu",
        "Fri",
        "Sat",
        "Sun"
      ],
      "scale": {
        "paddingInner": 0.1
      },
      "axis": {
        "title": null,
        "ticks": false,
        "domain": false,
        "labelOpacity": {
          "expr": "extent(pluck(data('hours'), 'doc_count'))[1] > 0 ? 1 : 0"
        }
      }
    },
    "tooltip": [
      {
        "field": "when",
        "title": "Hour"
      },
      {
        "field": "eventsText",
        "title": "Events"
      }
    ]
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "cornerRadius": 2,
        "color": "#98A8C3",
        "opacity": {
          "expr": "extent(pluck(data('hours'), 'doc_count'))[1] > 0 ? 0.15 : 0"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.doc_count > 0 && !datum.partial"
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": 2
      },
      "encoding": {
        "color": {
          "field": "doc_count",
          "type": "quantitative",
          "scale": {
            "type": "log",
            "range": [
              "#54B399",
              "#6092C0",
              "#9170B8",
              "#D36086"
            ],
            "interpolate": "hcl"
          },
          "legend": {
            "title": "Events / hour",
            "orient": "right",
            "direction": "vertical",
            "gradientLength": 140,
            "gradientThickness": 10,
            "values": {
              "expr": "!(extent(pluck(data('hours'), 'doc_count'))[1] > 0) ? [] : floor(log(domain('color')[1]) / LN10 + 1e-9) - ceil(log(domain('color')[0]) / LN10 - 1e-9) >= 1 ? slice([1, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000], ceil(log(domain('color')[0]) / LN10 - 1e-9), 1 + floor(log(domain('color')[1]) / LN10 + 1e-9)) : domain('color')[1] > 3 * domain('color')[0] ? [domain('color')[0], sqrt(domain('color')[0] * domain('color')[1]), domain('color')[1]] : domain('color')[1] > domain('color')[0] ? domain('color') : [domain('color')[0]]"
            },
            "labelExpr": "format(datum.value, '.2~s')",
            "titleOpacity": {
              "expr": "extent(pluck(data('hours'), 'doc_count'))[1] > 0 ? 1 : 0"
            },
            "labelOpacity": {
              "expr": "extent(pluck(data('hours'), 'doc_count'))[1] > 0 ? 1 : 0"
            },
            "gradientOpacity": {
              "expr": "extent(pluck(data('hours'), 'doc_count'))[1] > 0 ? 1 : 0"
            }
          }
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.partial && datum.doc_count > 0"
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": 2,
        "fillOpacity": 0,
        "stroke": "#98A8C3",
        "strokeWidth": 1.5,
        "strokeDash": [
          3,
          2
        ]
      }
    }
  ]
}
